<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
$user=app_require_permission('wholesale.manage');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wholesale Commerce Setup</title><style>:root{--bg:#f2f1ed;--panel:#fff;--ink:#171815;--muted:#6b706a;--line:#deded8;--accent:#d94a2b;--dark:#171b1a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}button,input,select,textarea{font:inherit}.top{height:64px;display:flex;justify-content:space-between;align-items:center;padding:0 22px;background:#fff;border-bottom:1px solid var(--line)}.btn{padding:9px 12px;border:1px solid var(--line);border-radius:9px;background:#fff;color:var(--ink);font-size:10px;font-weight:850;text-decoration:none;cursor:pointer}.btn.primary{background:var(--accent);color:#fff;border-color:var(--accent)}.shell{max-width:1350px;margin:auto;padding:26px}.hero h1{font-size:38px;letter-spacing:-.05em;margin:6px 0}.hero p{color:var(--muted);font-size:11px}.eyebrow{color:var(--accent);font-size:9px;font-weight:950;text-transform:uppercase}.cols{display:grid;grid-template-columns:1fr 1fr;gap:12px}.panel{background:#fff;border:1px solid var(--line);border-radius:15px;padding:16px}.panel h2{margin:0 0 4px;font-size:15px}.panel>p{color:var(--muted);font-size:9px;margin:0 0 12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide{grid-column:1/-1}.field{width:100%;min-height:40px;border:1px solid var(--line);border-radius:9px;padding:8px 9px}.list{display:grid;gap:7px;margin-top:12px}.row{padding:10px;border:1px solid var(--line);border-radius:10px;font-size:10px}.row strong{display:block}.row small{color:var(--muted)}label{font-size:8px;font-weight:900;color:#5b605b;display:block;margin-bottom:4px}.status{position:fixed;right:18px;bottom:18px;background:#171b1a;color:#fff;border-radius:10px;padding:10px 13px;font-size:10px;display:none}@media(max-width:850px){.cols,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><header class="top"><strong>Wholesale Commerce Setup</strong><div><a class="btn" href="wholesale-accounts.php">Customer Accounts</a> <a class="btn" href="wholesale-pipeline.php">Pipeline</a></div></header><main class="shell"><div class="hero"><span class="eyebrow">W1 commerce contract</span><h1>Catalog, SKUs & price lists</h1><p>Define sellable wholesale products once, then price them by canonical SKU. Quotes and orders use server-resolved prices and immutable line snapshots.</p></div><div class="cols"><section class="panel"><h2>Products & SKUs</h2><p>Create a product and its wholesale pack / sell unit.</p><div class="grid"><div><label>Product name</label><input class="field" id="pName"></div><div><label>Category</label><input class="field" id="pCategory"></div><div><label>Recipe mapping</label><select class="field" id="pRecipe"><option value="">No recipe mapping</option></select></div><div class="wide"><button class="btn primary" id="addProduct">Add product</button></div></div><div class="list" id="products"></div><div class="grid" style="margin-top:14px"><div><label>Product</label><select class="field" id="sProduct"></select></div><div><label>SKU</label><input class="field" id="sSku" placeholder="GEL-PIS-5L"></div><div><label>SKU name</label><input class="field" id="sName" placeholder="Pistachio 5L pan"></div><div><label>Sell UOM</label><input class="field" id="sUom" value="pan"></div><div><label>Minimum quantity</label><input class="field" id="sMin" type="number" step=".01" value="1"></div><div><label>Quantity increment</label><input class="field" id="sInc" type="number" step=".01" value="1"></div><div><label>Recipe yield / batch</label><input class="field" id="sYield" type="number" step=".01"></div><div><label>Recipe yield unit</label><input class="field" id="sYieldUnit" placeholder="pan"></div><div class="wide"><button class="btn primary" id="addSku">Add SKU</button></div></div><div class="list" id="skus"></div></section><section class="panel"><h2>Price lists</h2><p>Maintain effective-dated pricing without changing historical quote/order snapshots.</p><div class="grid"><div><label>Price list name</label><input class="field" id="lName" value="Standard Wholesale"></div><div><label>Order minimum</label><input class="field" id="lMin" type="number" step=".01" value="0"></div><div><label><input type="checkbox" id="lDefault"> Default price list</label></div><div><button class="btn primary" id="addList">Add price list</button></div></div><div class="list" id="lists"></div><div class="grid" style="margin-top:14px"><div><label>Price list</label><select class="field" id="priceList"></select></div><div><label>SKU</label><select class="field" id="priceSku"></select></div><div><label>Unit price</label><input class="field" id="unitPrice" type="number" step=".0001"></div><div><label>MOQ override</label><input class="field" id="priceMin" type="number" step=".01"></div><div><label>Effective from</label><input class="field" id="priceFrom" type="date"></div><div><button class="btn primary" id="setPrice">Add price</button></div></div></section></div></main><div class="status" id="status"></div><script>window.WC={csrf:<?=json_encode(app_csrf_token(),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>};</script><script>(()=>{const cfg=window.WC,esc=s=>String(s??'').replace(/[&<>]/g,''),status=t=>{const e=document.getElementById('status');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',1800)};let data={};async function req(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(opt.headers||{})},...opt}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}async function post(body){return req('api/wholesale-commerce.php',{method:'POST',body:JSON.stringify({...body,csrf_token:cfg.csrf})})}async function load(){data=await req('api/wholesale-commerce.php?action=admin');document.getElementById('products').innerHTML=(data.products||[]).map(p=>`<div class="row"><strong>${esc(p.name)}</strong><small>${esc(p.category||'Uncategorized')}${p.recipe_name?' · recipe '+esc(p.recipe_name):''}</small></div>`).join('');document.getElementById('skus').innerHTML=(data.skus||[]).map(s=>`<div class="row"><strong>${esc(s.sku)} · ${esc(s.name)}</strong><small>${esc(s.product_name)} · min ${s.minimum_quantity} · ${esc(s.sell_uom)}</small></div>`).join('');document.getElementById('lists').innerHTML=(data.priceLists||[]).map(l=>`<div class="row"><strong>${esc(l.name)}${Number(l.is_default)?' · default':''}</strong><small>Order minimum $${Number(l.minimum_order_amount||0).toFixed(2)}</small></div>`).join('');document.getElementById('sProduct').innerHTML=(data.products||[]).map(p=>`<option value="${p.public_id}">${esc(p.name)}</option>`).join('');document.getElementById('pRecipe').innerHTML='<option value="">No recipe mapping</option>'+(data.recipes||[]).map(r=>`<option value="${r.public_id}">${esc(r.name)}</option>`).join('');document.getElementById('priceList').innerHTML=(data.priceLists||[]).map(l=>`<option value="${l.public_id}">${esc(l.name)}</option>`).join('');document.getElementById('priceSku').innerHTML=(data.skus||[]).map(s=>`<option value="${s.public_id}">${esc(s.sku)} · ${esc(s.name)}</option>`).join('')}document.getElementById('addProduct').onclick=async()=>{try{await post({action:'product',name:pName.value,category:pCategory.value,recipeId:pRecipe.value});status('Product saved');load()}catch(e){alert(e.message)}};document.getElementById('addSku').onclick=async()=>{try{await post({action:'sku',productId:sProduct.value,sku:sSku.value,name:sName.value,sellUom:sUom.value,minimumQuantity:sMin.value,quantityIncrement:sInc.value,recipeYieldPerBatch:sYield.value,recipeYieldUnit:sYieldUnit.value});status('SKU saved');load()}catch(e){alert(e.message)}};document.getElementById('addList').onclick=async()=>{try{await post({action:'price_list',name:lName.value,minimumOrderAmount:lMin.value,isDefault:lDefault.checked});status('Price list saved');load()}catch(e){alert(e.message)}};document.getElementById('setPrice').onclick=async()=>{try{await post({action:'price',priceListId:priceList.value,skuId:priceSku.value,unitPrice:unitPrice.value,minimumQuantity:priceMin.value,effectiveFrom:priceFrom.value});status('Price added');load()}catch(e){alert(e.message)}};priceFrom.value=new Date().toISOString().slice(0,10);load()})();</script></body></html>
